userDefinedLinkHintCss:
/* Generated by theme-ssot — do not edit by hand */
:root {
  --vimium-accent: #90c6c2;
  --vimium-accent-fg: #1a1008;
  --vimium-secondary: #b1c7c5;
  --vimium-tertiary: #c2ba9c;
  --vimium-outline: #8ba7a5;
  --vimium-text: #ebe1d4;
  --vimium-muted: #d1c5b4;
  --vimium-surface2: #526659;
  --vimium-surface1: #37443c;
  --vimium-surface0: #2e3832;
  --vimium-base: #202723;
  --vimium-mantle: #252d28;

  --vimium-foreground-text-color: #ebe1d4;
  --vimium-background-text-color: #ebe1d4;
  --vimium-foreground-color: #252d28;
}

/* Hints: hardcoded hex (no var()) so defaults cannot win if :root fails */
div > .vimiumHintMarker,
div.vimiumHintMarker,
div.internal-vimium-hint-marker {
  background: #90c6c2 !important;
  background-image: none !important;
  border: 1px solid #252d28 !important;
  box-shadow: none !important;
  padding: 3px 4px !important;
}

div > .vimiumHintMarker span,
div.vimiumHintMarker span,
div.internal-vimium-hint-marker span {
  color: #1a1008 !important;
  font-weight: bold !important;
  font-size: 12px !important;
  text-shadow: none !important;
}

div > .vimiumHintMarker > .matchingCharacter,
div.vimiumHintMarker > .matchingCharacter,
div.internal-vimium-hint-marker > .matchingCharacter {
  color: #526659 !important;
}

/* vomnibar */
#vomnibar {
  background: #202723 !important;
  border: 2px solid #8ba7a5 !important;
}

#vomnibar input,
#vomnibar #vomnibar-search-area,
#vomnibar ul {
  color: #ebe1d4 !important;
  background: #202723 !important;
  border: none !important;
  box-shadow: none !important;
}

#vomnibar li {
  border-bottom: 1px solid #2e3832 !important;
}

#vomnibar li .source {
  color: #c2ba9c !important;
}

#vomnibar li em,
#vomnibar li .title,
#vomnibar li .title .match,
#vomnibar li .match {
  color: #90c6c2 !important;
  font-weight: bold !important;
}

#vomnibar li .url {
  color: #b1c7c5 !important;
}

#vomnibar li.selected {
  background-color: #2e3832 !important;
}

/* hud */
div#hud-container {
  background: #202723 !important;
  border: 1px solid #ebe1d4 !important;
  box-shadow: none !important;
}

div#hud-container span#hud-find-input,
div#hud-container div#hud {
  color: #ebe1d4 !important;
}

div#hud-container .hud-find,
div#hud-container #search-area {
  background-color: #202723 !important;
}

::selection {
  background-color: #c2ba9c !important;
  color: #1a1008 !important;
}
